import csv

with open('weoapr2025all.xls', 'r', encoding='utf-16-le') as f:
    reader = csv.reader(f, delimiter='\t')
    header = next(reader)
    header = [h.strip().replace('\ufeff','') for h in header]

    year_cols = {}
    for i, h in enumerate(header):
        if h.isdigit():
            year_cols[int(h)] = i

    print(f"Year range: {min(year_cols.keys())} - {max(year_cols.keys())}")

    targets = ['NGDP_RPCH', 'NGDP', 'NGDPD', 'NGDP_D']
    for row in reader:
        row = [c.strip() for c in row]
        if len(row) > 4:
            iso = row[1]
            subject = row[2]
            if iso == 'GEO' and subject in targets:
                print(f"\n--- {row[4]} ({subject}) ---")
                print(f"  Units: {row[6]}, Scale: {row[7]}")
                for yr in range(2020, 2031):
                    if yr in year_cols:
                        val = row[year_cols[yr]] if year_cols[yr] < len(row) else 'N/A'
                        print(f"  {yr}: {val}")
PYEOF
